import { model, Schema } from "mongoose";
import { DISEASE_LIMITS, DiseaseCategories, DiseaseSeverities } from "./disease.constants.js";
import type { TDisease } from "./disease.interface.js";

const diseaseSchema = new Schema<TDisease>(
  {
    //generated by generateDiseaseCode (DIS-00001) and never accepted from the client
    diseaseCode: {
      type: String,
      required: true,
      unique: true,
      immutable: true,
      trim: true,
      uppercase: true,
    },
    diseaseName: { type: String, required: true, trim: true, maxlength: DISEASE_LIMITS.maxNameLength },
    category: { type: String, enum: Object.values(DiseaseCategories), required: true },
    symptoms: { type: [{ type: String, trim: true }], default: [] },
    causes: { type: [{ type: String, trim: true }], default: [] },
    prevention: { type: String, trim: true, maxlength: DISEASE_LIMITS.maxPreventionLength },
    severity: { type: String, enum: Object.values(DiseaseSeverities), required: true },
    contagious: { type: Boolean, required: true, default: false },
    //validated against the Vaccine collection in the service
    recommendedVaccineIds: { type: [{ type: Schema.Types.ObjectId, ref: "Vaccine" }], default: [] },
    description: { type: String, trim: true, maxlength: DISEASE_LIMITS.maxDescriptionLength },
    //deactivated instead of deleted so Treatment / Vaccine references never break
    isActive: { type: Boolean, required: true, default: true },
  },
  { timestamps: true },
);

//one canonical record per name, case-insensitively (normalized variants are caught in the service)
diseaseSchema.index(
  { diseaseName: 1 },
  { unique: true, collation: { locale: "en", strength: 2 } },
);

//selection screens: active diseases by category; symptom reference search; vaccine mapping
diseaseSchema.index({ isActive: 1, category: 1 });
diseaseSchema.index({ isActive: 1, severity: 1 });
diseaseSchema.index({ symptoms: 1 });
diseaseSchema.index({ recommendedVaccineIds: 1 });

export const DiseaseModel = model<TDisease>("Disease", diseaseSchema);
